import os
import requests

def submit_datadog_log_event(log_data: dict) -> dict:
    api_key = os.environ.get("DD_API_KEY")
    app_key = os.environ.get("DD_APP_KEY")
    if not api_key or not app_key:
        raise ValueError("DD_API_KEY and DD_APP_KEY environment variables must be set.")

    headers = {
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key,
        "Content-Type": "application/json",
    }

    payload = {
        "data": {
            "type": "log",
            "attributes": {
                "message": log_data.get("message", ""),
                "status": log_data.get("status", "info"),
                "service": log_data.get("service", ""),
                "hostname": log_data.get("hostname", ""),
                **{k: v for k, v in log_data.items() if k not in ("message", "status", "service", "hostname")}
            }
        }
    }

    response = requests.post(
        "https://http-intake.logs.datadoghq.com/api/v2/logs",
        headers=headers,
        json=payload
    )
    response.raise_for_status()
    return response.json() if response.content else {}
